<div class="page-heading jobcard-heading"><div><h1><?= e(ucfirst($status)) ?> Job Cards</h1><nav class="job-breadcrumb"><a href="index.php?page=admin">Dashboard</a><span>›</span><a href="index.php?page=admin&amp;section=jobcards-pending">Job Cards</a><span>›</span><strong><?= e(ucfirst($status)) ?> Job Cards</strong></nav></div><a class="btn btn-danger" href="index.php?page=admin&amp;section=jobcards-new">＋ New Job Card</a></div>
<form class="admin-panel jobcard-filter-panel" method="get"><input type="hidden" name="page" value="admin"><input type="hidden" name="section" value="<?= e($section) ?>"><div class="job-filter-grid"><label>Search<input class="form-control" name="search" value="<?= e($filters['search']) ?>" placeholder="Search by Job Card No, Vehicle No, Customer Name..."></label><label>Mechanic<select class="form-select" name="mechanic_id"><option value="0">All Mechanics</option><?php foreach($lookups['employees'] as $employee): ?><option value="<?= (int)$employee['id'] ?>" <?= $filters['mechanic_id']==(int)$employee['id']?'selected':'' ?>><?= e($employee['name']) ?></option><?php endforeach; ?></select></label><label>Bay<select class="form-select" name="bay_name"><option value="">All Bays</option><?php foreach($lookups['bays'] as $bay): ?><option <?= $filters['bay_name']===$bay['bay_name']?'selected':'' ?>><?= e($bay['bay_name']) ?></option><?php endforeach; ?></select></label><label>Priority<select class="form-select" name="priority"><option value="">All Priorities</option><?php foreach(['low','normal','high','urgent'] as $priority): ?><option value="<?= $priority ?>" <?= $filters['priority']===$priority?'selected':'' ?>><?= ucfirst($priority) ?></option><?php endforeach; ?></select></label></div><div class="job-filter-bottom"><label>From Date<input class="form-control" type="date" name="date_from" value="<?= e($filters['date_from']) ?>"></label><label>To Date<input class="form-control" type="date" name="date_to" value="<?= e($filters['date_to']) ?>"></label><a class="btn btn-light" href="index.php?page=admin&amp;section=<?= e($section) ?>">Clear</a><button class="btn btn-danger">Search</button></div></form>
<section class="admin-panel jobcard-list jobcard-list-screen"><div class="panel-heading"><h2><?= ucfirst($status) ?> Job Cards <span class="service-count-badge"><?= count($rows) ?></span></h2><div class="jobcard-tabs"><a class="<?= $status==='pending'?'active':'' ?>" href="index.php?page=admin&amp;section=jobcards-pending">Pending</a><a class="<?= $status==='ongoing'?'active':'' ?>" href="index.php?page=admin&amp;section=jobcards-ongoing">Ongoing</a><a class="<?= $status==='completed'?'active':'' ?>" href="index.php?page=admin&amp;section=jobcards-completed">Completed</a></div></div><div class="table-responsive"><table class="table admin-table jobcard-list-table"><thead><tr><th>Job Card No.</th><th>Vehicle Details</th><th>Customer Details</th><th>Job Summary</th><th>Priority</th><th>Created On</th><th>Actions</th></tr></thead><tbody><?php if(!$rows): ?><tr><td colspan="7" class="empty-table">No <?= e($status) ?> job cards found.</td></tr><?php else: foreach($rows as $row): ?><tr><td><a class="jobcard-number" href="index.php?page=admin&amp;section=jobcards-view&amp;id=<?= (int)$row['id'] ?>"><?= e($row['job_card_no']) ?></a><span class="service-status service-status-<?= e($row['status']) ?>"><?= e(strtoupper($row['status'])) ?></span><small>⌂ <?= e($row['bay_name']?:'No bay') ?></small></td><td><strong>▣ <?= e($row['vehicle_number']?:'-') ?></strong><small><?= e(trim(($row['vehicle_type']?:'').'  |  '.($row['make']?:'').' '.($row['model']?:''))) ?></small><small><?= e($row['colour']?:'') ?> <?= $row['year']?' | '.(int)$row['year']:'' ?> <?= $row['current_mileage']?' | '.number_format((float)$row['current_mileage']).' KM':'' ?></small></td><td><strong>♙ <?= e($row['customer_name']) ?></strong><small>♧ <?= e($row['contact_number']) ?></small></td><td><span class="job-summary-text"><?= e($row['complaint'] ?: ($row['requested_work'] ?: '-')) ?></span><small><?= (int)$row['item_count'] ?> item<?= (int)$row['item_count']===1?'':'s' ?> · <?= e($row['mechanic_name']?:'No mechanic') ?></small></td><td><span class="job-priority job-priority-<?= e($row['priority']) ?>"><?= ucfirst($row['priority']) ?></span></td><td><?= e(date('d M Y',strtotime($row['created_at']))) ?><small><?= e(date('h:i A',strtotime($row['created_at']))) ?></small></td><td><div class="job-row-actions"><a class="btn btn-light btn-sm" href="index.php?page=admin&amp;section=jobcards-view&amp;id=<?= (int)$row['id'] ?>">◉ View</a><?php if(in_array($status, ['pending', 'ongoing'], true)): ?><a class="btn btn-light btn-sm" href="index.php?page=admin&amp;section=jobcards-edit&amp;id=<?= (int)$row['id'] ?>">✎ Edit</a><form method="post" action="index.php?page=admin&amp;section=jobcards-delete" onsubmit="return confirm('Delete this job card? This action cannot be undone.');"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="job_card_id" value="<?= (int)$row['id'] ?>"><button class="btn btn-outline-danger btn-sm" type="submit">⌫ Delete</button></form><?php endif; ?><?php if($status==='pending'): ?><form method="post" action="index.php?page=admin&amp;section=jobcards-action"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="job_card_id" value="<?= (int)$row['id'] ?>"><input type="hidden" name="action" value="start"><button class="btn btn-primary btn-sm">▷ Start</button></form><?php endif; ?></div></td></tr><?php endforeach; endif; ?></tbody></table></div><div class="jobcard-list-footer"><span>Showing 1 to <?= count($rows) ?> of <?= count($rows) ?> job cards</span><div><button class="btn btn-light btn-sm" disabled>‹ Prev</button><button class="btn btn-danger btn-sm">1</button><button class="btn btn-light btn-sm" disabled>Next ›</button></div></div></section>
